from typing import List, Optional, Tuple

import torch
import torch.distributed as dist
import torch.nn.functional as F


def _get_rank_and_world_size() -> Tuple[int, int]:
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank(), dist.get_world_size()
    return 0, 1


def _partition_layers(num_layers: int, world_size: int, rank: int) -> Tuple[int, int]:
    layers_per_rank = num_layers // world_size
    remainder = num_layers % world_size
    start = rank * layers_per_rank + min(rank, remainder)
    end = start + layers_per_rank + (1 if rank < remainder else 0)
    return start, end


def _filter_kwargs(func, **kwargs):
    params = inspect.signature(func).parameters
    filtered = {}
    for name in params:
        if name == "self":
            continue
        if name in kwargs:
            filtered[name] = kwargs[name]
    return filtered


def _prepare_attention_mask(
    model,
    attention_mask: torch.Tensor,
    input_shape: Tuple[int, int],
    inputs_embeds: torch.Tensor,
    cache_position: Optional[torch.Tensor] = None,
    past_key_values_length: int = 0,
) -> torch.Tensor:
    if hasattr(model, "_update_causal_mask"):
        return _filter_kwargs(
            model._update_causal_mask,
            attention_mask=attention_mask,
            inputs_embeds=inputs_embeds,
            cache_position=cache_position,
            past_key_values_length=past_key_values_length,
            output_attentions=False,
        )
    if hasattr(model, "_prepare_decoder_attention_mask"):
        return model._prepare_decoder_attention_mask(
            attention_mask, input_shape, inputs_embeds, past_key_values_length
        )
    if hasattr(model, "_prepare_4d_causal_attention_mask"):
        return _filter_kwargs(
            model._prepare_4d_causal_attention_mask,
            attention_mask=attention_mask,
            input_shape=input_shape,
            inputs_embeds=inputs_embeds,
            past_key_values_length=past_key_values_length,
        )
    if hasattr(model, "_prepare_4d_causal_attention_mask_for_sdpa"):
        return _filter_kwargs(
            model._prepare_4d_causal_attention_mask_for_sdpa,
            attention_mask=attention_mask,
            input_shape=input_shape,
            inputs_embeds=inputs_embeds,
            past_key_values_length=past_key_values_length,
        )

    # Fallback implementation mirroring modeling_attn_mask_utils
    bsz, tgt_len = input_shape
    dtype = inputs_embeds.dtype
    device = inputs_embeds.device
    min_val = torch.finfo(dtype).min

    causal_mask = torch.full((tgt_len, tgt_len), min_val, device=device, dtype=dtype)
    causal_mask = torch.triu(causal_mask, diagonal=1)
    causal_mask = causal_mask[None, None, :, :].expand(bsz, 1, tgt_len, tgt_len)

    expanded_mask = attention_mask[:, None, None, :].expand(bsz, 1, tgt_len, tgt_len)
    expanded_mask = expanded_mask.to(dtype)
    inverted_mask = 1.0 - expanded_mask
    expanded_mask = inverted_mask.masked_fill(inverted_mask.to(torch.bool), min_val)

    return expanded_mask + causal_mask


def _layer_forward(
    layer,
    hidden_states: torch.Tensor,
    attention_mask: torch.Tensor,
    position_ids: torch.Tensor,
    cache_position: Optional[torch.Tensor],
) -> torch.Tensor:
    kwargs = {
        "attention_mask": attention_mask,
        "position_ids": position_ids,
        "past_key_value": None,
        "use_cache": False,
        "output_attentions": False,
        "cache_position": cache_position,
    }
    params = inspect.signature(layer.forward).parameters
    if "position_embeddings" in params:
        rotary = getattr(layer, "self_attn", None)
        position_embeddings = None
        if rotary is not None and hasattr(rotary, "rotary_emb"):
            try:
                position_embeddings = rotary.rotary_emb(hidden_states, position_ids)
            except TypeError:
                try:
                    position_embeddings = rotary.rotary_emb(hidden_states, seq_len=hidden_states.shape[1])
                except Exception:
                    position_embeddings = None
        if position_embeddings is not None:
            kwargs["position_embeddings"] = position_embeddings
    filtered_kwargs = _filter_kwargs(layer.forward, **kwargs)
    outputs = layer(hidden_states, **filtered_kwargs)
    if isinstance(outputs, tuple):
        return outputs[0]
    return outputs


def _get_hidden_size(model) -> int:
    if hasattr(model, "config") and hasattr(model.config, "hidden_size"):
        return model.config.hidden_size
    if hasattr(model, "model") and hasattr(model.model, "embed_tokens"):
        return model.model.embed_tokens.embedding_dim
    if hasattr(model, "embed_tokens"):
        return model.embed_tokens.embedding_dim
    raise AttributeError("Unable to infer hidden size from model")


def _get_lm_head(model):
    if hasattr(model, "lm_head"):
        return model.lm_head
    if hasattr(model, "get_output_embeddings"):
        return model.get_output_embeddings()
    raise AttributeError("Model does not expose an lm_head")


def train_step_pipeline_afab(model, inputs: List[torch.Tensor], targets: List[torch.Tensor], device, dtype):
    rank, world_size = _get_rank_and_world_size()
    is_first = rank == 0
    is_last = rank == world_size - 1

    model.train()

    layers = model.model.layers
    num_layers = len(layers)
    start_idx, end_idx = _partition_layers(num_layers, world_size, rank)
    local_layers = layers[start_idx:end_idx]

    hidden_size = _get_hidden_size(model)

    input_cache: List[Optional[torch.Tensor]] = []
    output_cache: List[torch.Tensor] = []
    loss_cache: List[torch.Tensor] = []

    microbatches = len(inputs)

    for mb_idx in range(microbatches):
        input_ids = inputs[mb_idx].to(device)
        batch_size, seq_len = input_ids.shape

        if is_last:
            target_ids = targets[mb_idx].to(device)
        else:
            target_ids = None

        position_ids = torch.arange(seq_len, device=device).unsqueeze(0).expand(batch_size, -1)
        cache_position = torch.arange(seq_len, device=device)

        if is_first:
            hidden_states = model.model.embed_tokens(input_ids)
            if hidden_states.dtype != dtype:
                hidden_states = hidden_states.to(dtype)
        else:
            hidden_states = torch.empty(
                (batch_size, seq_len, hidden_size), device=device, dtype=dtype
            )
            if world_size > 1:
                dist.recv(hidden_states, src=rank - 1)
            hidden_states.requires_grad_(True)

        base_attention_mask = torch.ones((batch_size, seq_len), device=device)
        attention_mask = _prepare_attention_mask(
            model.model,
            base_attention_mask,
            (batch_size, seq_len),
            hidden_states,
            cache_position=cache_position,
            past_key_values_length=0,
        )

        input_cache.append(hidden_states if not is_first else None)

        for layer in local_layers:
            hidden_states = _layer_forward(
                layer, hidden_states, attention_mask, position_ids, cache_position
            )

        if hidden_states.dtype != dtype:
            hidden_states = hidden_states.to(dtype)

        output_cache.append(hidden_states)

        if is_last:
            if hasattr(model.model, "norm"):
                hidden_states = model.model.norm(hidden_states)
            lm_head = _get_lm_head(model)
            logits = lm_head(hidden_states)
            loss = F.cross_entropy(
                logits.reshape(-1, logits.size(-1)), target_ids.reshape(-1)
            )
            loss = loss / microbatches
            loss_cache.append(loss)
        else:
            if world_size > 1:
                dist.send(hidden_states.detach().contiguous(), dst=rank + 1)

    for mb_idx in reversed(range(microbatches)):
        if is_last:
            loss = loss_cache[mb_idx]
            loss.backward()
            if not is_first and world_size > 1:
                grad_to_send = input_cache[mb_idx].grad
                dist.send(grad_to_send.contiguous(), dst=rank - 1)
        else:
            grad_output = torch.empty_like(output_cache[mb_idx], device=device, dtype=dtype)
            if world_size > 1:
                dist.recv(grad_output, src=rank + 1)
            output_cache[mb_idx].backward(grad_output)
            if rank > 0 and world_size > 1:
                grad_to_send = input_cache[mb_idx].grad
                dist.send(grad_to_send.contiguous(), dst=rank - 1)

    if is_last:
        total_loss = torch.stack([loss.detach() for loss in loss_cache]).sum()
        return total_loss
    return None
"}

